    _b = TB.zaehle(c, quelle_kette="rollen")
    _live = TB.merkmale(
        vola_perzentil=TB._prozent(familien["schwankung_perzentil"]),
        spanne_perzentil=TB._prozent(familien["momentum_perzentil"]),
        gleichlauf=TB._band_grob(familien["volumen_perzentil"]))
